"""Read the selected sample only; never saves pricing, consent, orders or balances."""
import pathlib,json,importlib.util,decimal,subprocess,datetime
R=pathlib.Path(__file__).resolve().parents[1];O=pathlib.Path('/private/tmp/finance84');sp=importlib.util.spec_from_file_location('c',R/'scripts/capture-financial-readers-63.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)
def encode(value):return int(value) if isinstance(value,decimal.Decimal) and value%1==0 else float(value) if isinstance(value,decimal.Decimal) else str(value)
def main():
 db=m.session().resource('dynamodb');sample=json.loads((R/'frontend/finance-sample-64.json').read_text());pk='COMMERCIAL_AGREEMENT#'+sample['agreement']['id'];rows={}
 for label,table,key in [('pricingCurrent','staging-PlatformStaff',{'pk':'OPERATIONAL_SETTINGS#DELIVERY_PRICING','sk':'CURRENT'}),('pricingDraft','staging-PlatformStaff',{'pk':'OPERATIONAL_SETTINGS#DELIVERY_PRICING','sk':'DRAFT'}),('agreementDraft','staging-MerchantPlatform',{'pk':pk,'sk':'DRAFT'}),('agreementCurrent','staging-MerchantPlatform',{'pk':pk,'sk':'CURRENT'})]:rows[label]=db.Table(table).get_item(Key=key,ConsistentRead=True).get('Item')
 d=rows['agreementDraft'];c=rows['agreementCurrent'];rows['consent']=db.Table('staging-MerchantPlatform').get_item(Key={'pk':pk,'sk':'CONSENT#'+str(d['version'])},ConsistentRead=True).get('Item') if d else None
 # Publication increments the draft version without manufacturing a second consent.
 if d and c and not rows['consent'] and d.get('publishedVersion')==c.get('version') and d['version']>1:
  rows['consent']=db.Table('staging-MerchantPlatform').get_item(Key={'pk':pk,'sk':'CONSENT#'+str(d['version']-1)},ConsistentRead=True).get('Item')
 for label,table,sk in [('agreementVersion','staging-MerchantPlatform','VERSION#'),('acceptance','staging-MerchantPlatform','ACCEPTANCE#'),('authorization','staging-PlatformStaff','APPROVAL#')]:rows[label]=db.Table(table).get_item(Key={'pk':pk,'sk':sk+str(c['version'])},ConsistentRead=True).get('Item') if c else None
 rows['branch']=db.Table('WhizzMerchants_Businesses').get_item(Key={'businessId':sample['businessId']},ConsistentRead=True,ProjectionExpression='businessId,commercialAgreementId,commercialAgreementVersion').get('Item')
 (O/'saved-sample.private.json').write_text(json.dumps(rows,default=encode,ensure_ascii=False,indent=2))
 node="""const fs=require('fs'),r=JSON.parse(fs.readFileSync(0,'utf8')),sample=require('./frontend/finance-sample-64.json'),{quoteHash}=require('./backend/wallet-service/dist/deliveryQuoteRecord'),{validatePricingRules}=require('./backend/wallet-service/dist/deliveryPricing');let pricesMatch=false;try{const p=validatePricingRules(r.pricingCurrent.values),strip=v=>{const x=structuredClone(v);delete x.status;return x;};pricesMatch=['deliveryRules','driverRules'].every(k=>sample.pricing[k].every(rule=>p[k].some(a=>quoteHash(strip(a))===quoteHash(strip(rule)))));}catch{}const d=r.agreementDraft,c=r.agreementCurrent,a=r.acceptance,v=r.agreementVersion,z=r.authorization;console.log(JSON.stringify({pricingPublished:!!r.pricingCurrent,pricingVersion:r.pricingCurrent?.version??null,pricesMatchApprovedSample:pricesMatch,agreementSaved:!!d,agreementMatchesApprovedSample:!!d&&quoteHash(d.values)===quoteHash(sample.agreement.values),ownerConsentPresent:!!r.consent&&r.consent.hash===d?.hash,agreementPublished:!!c,agreementVersion:c?.version??null,acceptanceAndAuthorizationMatch:!!a&&!!v&&!!z&&a.termsHash===v.termsHash&&z.termsHash===v.termsHash&&c?.termsHash===v.termsHash,branchAgreementLinked:r.branch?.commercialAgreementId===sample.agreement.id&&r.branch?.commercialAgreementVersion===c?.version}));"""
 result=json.loads(subprocess.run(['node','-e',node],input=json.dumps(rows,default=encode),text=True,capture_output=True,check=True,cwd=R).stdout);result.update(checkedAtUtc=datetime.datetime.now(datetime.timezone.utc).isoformat(),readOnly=True,part=84);(O/'sample-status.json').write_text(json.dumps(result,indent=2));print(json.dumps(result))
if __name__=='__main__':main()
